using symbol "std:io" @print;
function scale(x::i64)::i64 { x * 10 }
{
 let scale = 7;
 behave @print(scale);
 behave @print(scale(3));
};

using symbol "std:io" @print;
proc selected(x::i64) -> i64 { x + 20 }
proc apply(callback::proc(i64) -> i64, x::i64) -> i64 { callback(x) }
behave @print(apply(selected, 3));

using symbol "std:io" @print;
symbol @callback::proc(i64) -> i64;
proc selected(x::i64) -> i64 { x + 20 }
proc apply(callback::proc(i64) -> i64, x::i64) -> i64 {
 effect @callback <- callback;
 behave @callback(x)
}
behave @print(apply(selected, 3));

using symbol "std:io" @print;
proc selected(x::i64) -> i64 { x + 20 }
proc callback(x::i64) -> i64 { x + 1 }
proc apply(callback::proc(i64) -> i64, x::i64) -> i64 { callback(x) }
behave @print(apply(selected, 3));
